6	/**
7	 * POST /api/ocr
8	 *
9	 * Processes a file upload and extracts receipt data using OCR
10	 *
11	 * Request body (multipart/form-data):
12	 * - file: The image or PDF file to process
13	 *
14	 * Response:
15	 * - 200: { mimeType: string, category: 'pdf' | 'image', ocrData: ReceiptExtract }
16	 * - 400: Validation error
17	 * - 500: Processing error
18	 */
19	export const POST: RequestHandler = async ({ request }) => {
20		try {
21			// Parse form data
22			const formData = await request.formData();
23			const file = formData.get('file') as File;
24	
25			if (!file) {
26				throw error(400, 'No file uploaded. Please provide a file in the request.');
27			}
28	
29			// Convert file to buffer for validation
30			const arrayBuffer = await file.arrayBuffer();
31			const buffer = Buffer.from(arrayBuffer);
32	
33			// Validate file using magic number detection
34			const validation = await FileValidator.validateFile(buffer);
35	
36			if (!validation.isValid) {
37				throw error(400, validation.error || 'File validation failed');
38			}
39	
40			// At this point, validation.mimeType and validation.category are guaranteed to exist
41			const mimeType = validation.mimeType!;
42			const category = validation.category!;
43	
44			// Get file URL - in production, this should be a temporary signed URL
45			// For now, we'll need to pass the file content directly or upload to storage first
46			const fileUrl = formData.get('fileUrl') as string;
47	
48			if (!fileUrl) {
49				throw error(
50					400,
51					'fileUrl is required. Upload the file to storage first and provide the URL.'
52				);
53			}
54	
55			// Process with OCR
56			const ocrService = new OcrService();
57			const ocrData = await ocrService.extractFromUrl(fileUrl, mimeType);
58	
59			return json({
60				mimeType,
61				category,
62				ocrData
63			});
64		} catch (err) {
65			console.error('OCR API error:', err);
66	
67			// Re-throw SvelteKit errors
68			if (err && typeof err === 'object' && 'status' in err) {
69				throw err;
70			}
71	
72			// Handle other errors
73			const message = err instanceof Error ? err.message : 'Unknown error occurred';
74			throw error(500, `OCR processing failed: ${message}`);
75		}
76	};
