25		async function fetchReceipts() {
26			const { data, error } = await supabase
27				.from('receipts')
28				.select('id, receipt_image_path')
29				.not('receipt_image_path', 'is', null);
30	
31			if (error) {
32				alert('Failed to fetch receipts: ' + error.message);
33				return;
34			}
35	
36			receipts = (data || []).filter((r) => {
37				const path = r.receipt_image_path?.toLowerCase() || '';
38				return path.endsWith('.jpg') || path.endsWith('.jpeg') || path.endsWith('.png');
39			});
40		}
41	
42		async function downloadImage(path: string): Promise<Blob | null> {
43			try {
44				const { data, error } = await supabase.storage.from('receipts').download(path);
45				if (error) throw error;
46				return data;
47			} catch (err) {
48				console.error('Download failed:', err);
49				return null;
50			}
51		}
52	
53		async function uploadResizedImage(path: string, file: File): Promise<boolean> {
54			try {
55				// Delete old version
56				await supabase.storage.from('receipts').remove([path]);
57	
58				// Upload new version
59				const { error } = await supabase.storage.from('receipts').upload(path, file, {
60					contentType: file.type,
61					upsert: true
62				});
63	
64				if (error) throw error;
65				return true;
66			} catch (err) {
67				console.error('Upload failed:', err);
68				return false;
69			}
70		}
71	
72		async function processReceipt(receipt: Receipt): Promise<ProcessResult> {
73			const path = receipt.receipt_image_path!;
74	
75			// Download original
76			const blob = await downloadImage(path);
77			if (!blob) {
78				return { path, status: 'error', message: 'Failed to download' };
79			}
80	
81			// Convert to File
82			const filename = path.split('/').pop() || 'image.jpg';
83			const mimeType = path.toLowerCase().endsWith('.png') ? 'image/png' : 'image/jpeg';
84			const originalFile = new File([blob], filename, { type: mimeType });
85			const originalSize = originalFile.size;
86	
87			// Resize
88			try {
89				const resizedFile = await resizeImage(originalFile, 2000, 0.85);
90				const resizedSize = resizedFile.size;
91				const reduction = (1 - resizedSize / originalSize) * 100;
92	
93				// Only upload if smaller
94				if (resizedSize >= originalSize) {
95					return {
96						path,
97						status: 'skipped',
98						message: 'Already optimal size',
99						originalSize,
100						resizedSize
101					};
102				}
103	
104				// Upload resized version
105				const uploaded = await uploadResizedImage(path, resizedFile);
106				if (!uploaded) {
107					return { path, status: 'error', message: 'Upload failed', originalSize, resizedSize };
108				}
109	
110				return {
111					path,
112					status: 'success',
113					message: 'Resized and uploaded',
114					originalSize,
115					resizedSize,
116					reduction
117				};
118			} catch (err) {
119				return {
120					path,
121					status: 'error',
122					message: `Resize failed: ${err instanceof Error ? err.message : 'Unknown error'}`
123				};
124			}
125		}
126	
127		async function startProcessing() {
128			if (!confirm(`Resize ${receipts.length} images? This will replace the originals.`)) {
129				return;
130			}
131	
132			processing = true;
133			results = [];
134			currentIndex = 0;
135	
136			for (let i = 0; i < receipts.length; i++) {
137				currentIndex = i + 1;
138				const result = await processReceipt(receipts[i]);
139				results = [...results, result];
140			}
141	
142			processing = false;
143			alert('Processing complete!');
144		}
145	
146		onMount(() => {
147			fetchReceipts();
148		});
149	
150		let totalSaved = $derived(
151			results
152				.filter((r) => r.status === 'success' && r.originalSize && r.resizedSize)
153				.reduce((sum, r) => sum + (r.originalSize! - r.resizedSize!), 0)
154		);
155	
156		let successCount = $derived(results.filter((r) => r.status === 'success').length);
157		let skippedCount = $derived(results.filter((r) => r.status === 'skipped').length);
158		let errorCount = $derived(results.filter((r) => r.status === 'error').length);
159	</script>
