1	// Deno Deploy / Supabase Edge Function for Resend webhook.
2	//
3	// This file is the imperative SHELL: it wires the real runtime collaborators
4	// (Supabase service client, global fetch, Deno.env, the clock, Mistral OCR,
5	// the Bank of Canada rate lookup, and svix signature verification) into the
6	// injectable core `handleResendWebhook` in `handler.ts`. All request→response
7	// orchestration and branching lives in the core, where it is unit-tested under
8	// vitest. The only untested lines here are the dependency constructors and the
9	// one-line `Deno.serve` binding — deliberately trivial, matching the repo's
10	// "seam-only" testing philosophy.
11	import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
12	import { Webhook } from 'https://esm.sh/svix@1.15.0';
13	import { handleResendWebhook, type OcrPort } from './handler.ts';
14	import { ocrFromUrl, processEmailText, textToImage } from '../_shared/mistral.ts';
15	import { fetchExchangeRate } from '../_shared/exchangeRate.ts';
16	
17	/** Service-role client used to bypass RLS for webhook-driven inserts. */
18	function createServiceClient(url: string, key: string) {
19		return createClient(url, key, {
20			auth: { autoRefreshToken: false, persistSession: false }
21		});
22	}
23	
24	/**
25	 * Verifies the Resend webhook signature using the Svix library.
26	 * Based on: https://resend.com/docs/dashboard/webhooks/verify-webhooks-requests
27	 * Kept in the shell so the svix dependency never has to load under vitest.
28	 */
29	function verifyWebhookSignature(headers: Headers, payload: string, signingSecret: string): boolean {
30		const svixId = headers.get('svix-id');
31		const svixTimestamp = headers.get('svix-timestamp');
32		const svixSignature = headers.get('svix-signature');
33	
34		console.log('Signature verification headers:', {
35			hasSignature: !!svixSignature,
36			hasTimestamp: !!svixTimestamp,
37			hasId: !!svixId
38		});
39	
40		if (!svixId || !svixTimestamp || !svixSignature) {
41			console.error('Missing webhook signature headers:', {
42				signature: svixSignature ? 'present' : 'missing',
43				timestamp: svixTimestamp ? 'present' : 'missing',
44				id: svixId ? 'present' : 'missing'
45			});
46			return false;
47		}
48	
49		try {
50			const wh = new Webhook(signingSecret);
51	
52			// Verify the webhook - this will throw on error
53			wh.verify(payload, {
54				'svix-id': svixId,
55				'svix-timestamp': svixTimestamp,
56				'svix-signature': svixSignature
57			});
58	
59			console.log('Webhook signature verified successfully');
60			return true;
61		} catch (err) {
62			console.error('Webhook signature verification failed:', err);
63			return false;
64		}
65	}
66	
67	const denoEnv = (key: string): string | undefined => Deno.env.get(key);
68	
69	/** Real OCR collaborator — Mistral vision, with the injected fetch/env seam wired. */
70	const realOcr: OcrPort = {
71		processEmailText: (text) => processEmailText(text, { fetchFn: fetch, env: denoEnv }),
72		textToImage: (text) => textToImage(text),
73		ocrFromUrl: (fileUrl, mimeType) => ocrFromUrl(fileUrl, mimeType, { fetchFn: fetch, env: denoEnv })
74	};
75	
76	Deno.serve((req) =>
77		handleResendWebhook(req, {
78			supabase: createServiceClient(
79				Deno.env.get('SUPABASE_URL') ?? '',
80				Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
81			),
82			fetchFn: fetch,
83			env: denoEnv,
84			now: () => new Date(),
85			ocr: realOcr,
86			exchangeRate: (currency, date) => fetchExchangeRate(currency, date, fetch),
87			verifySignature: verifyWebhookSignature
88		})
89	);
